workflow_template_checklist.default:
{
  "metadata": {
    "name": "Template: checklist",
    "version": "1.0.0",
    "description": "Starting shape for a simple flow: steps done in order, no branches. Replace each step's directive with one step of the task and its completion condition with the observable result that shows the step is done. Add or remove steps as the task needs.",
    "schemaVersion": 1
  },
  "nodes": [
    {
      "id": "start",
      "type": "start",
      "connections": {
        "default": "first-step"
      }
    },
    {
      "id": "first-step",
      "type": "agent-directive",
      "directive": "Replace with the first step: what the agent does and what it produces.",
      "completionCondition": "Replace with the observable result of the first step, for example a file that exists or a message the user received.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "second-step"
      }
    },
    {
      "id": "second-step",
      "type": "agent-directive",
      "directive": "Replace with the second step.",
      "completionCondition": "Replace with the observable result of the second step.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "final-step"
      }
    },
    {
      "id": "final-step",
      "type": "agent-directive",
      "directive": "Replace with the last step, usually reporting the result to the user.",
      "completionCondition": "Replace with the observable result of the last step.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "end"
      }
    },
    {
      "id": "end",
      "type": "end"
    }
  ]
}

workflow_template_do_check_redo.default:
{
  "metadata": {
    "name": "Template: do, check, redo",
    "version": "1.0.0",
    "description": "Starting shape for a flow whose result is checked and redone until it passes. This is a review-and-redo loop, so it belongs to the standard tier, not the simple one. Replace the directives with the work, the check and what a redo must change.",
    "schemaVersion": 1
  },
  "nodes": [
    {
      "id": "start",
      "type": "start",
      "connections": {
        "default": "do-work"
      }
    },
    {
      "id": "do-work",
      "type": "agent-directive",
      "directive": "Replace with the work to do. On a redo, address every finding of the last check.",
      "completionCondition": "Replace with the observable result of the work.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "check-work"
      }
    },
    {
      "id": "check-work",
      "type": "agent-directive",
      "directive": "Replace with the check: compare the result with what was asked and answer pass or redo, with the findings for a redo.",
      "completionCondition": "The verdict names whether the result meets the check, with findings for a redo.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "verdict": {
            "type": "string",
            "enum": [
              "pass",
              "redo"
            ],
            "description": "pass when the result meets the check; redo when it must be done again"
          },
          "findings": {
            "type": "string",
            "description": "What the check found; required reading for the redo",
            "maxLength": 4000,
            "minLength": 1
          }
        },
        "required": [
          "verdict"
        ],
        "allOf": [
          {
            "if": {
              "properties": {
                "verdict": {
                  "const": "redo"
                }
              },
              "required": [
                "verdict"
              ]
            },
            "then": {
              "required": [
                "findings"
              ]
            }
          }
        ]
      },
      "connections": {
        "success": "end",
        "redo": "do-work"
      },
      "cases": [
        {
          "when": {
            "operator": "eq",
            "left": {
              "contextPath": "check-work.verdict"
            },
            "right": "redo"
          },
          "output": "redo"
        }
      ]
    },
    {
      "id": "end",
      "type": "end"
    }
  ]
}

workflow_template_approval_gate.default:
{
  "metadata": {
    "name": "Template: approval gate",
    "version": "1.0.0",
    "description": "Starting shape for a simple flow with one approval: the agent prepares something, the user approves or declines it, and the flow acts only on approval. Replace the directives with what is prepared, what the user is asked and what happens after approval.",
    "schemaVersion": 1
  },
  "nodes": [
    {
      "id": "start",
      "type": "start",
      "connections": {
        "default": "prepare"
      }
    },
    {
      "id": "prepare",
      "type": "agent-directive",
      "directive": "Replace with what the agent prepares for the user to decide on.",
      "completionCondition": "Replace with the observable result: what exists for the user to see.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "ask-approval"
      }
    },
    {
      "id": "ask-approval",
      "type": "agent-directive",
      "directive": "Show the user what was prepared and ask them to approve or decline it. Explain what each answer leads to: approving lets the workflow act on it, declining ends the run without acting. Say which answer you recommend and why, from what you saw in the prepared work. Record their answer in their words.",
      "completionCondition": "The user was told what approving and declining each lead to and why the agent recommends one, answered, and their answer is recorded.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "decision": {
            "type": "string",
            "enum": [
              "approved",
              "declined"
            ],
            "description": "The user's answer"
          },
          "note": {
            "type": "string",
            "description": "The user's words, especially on a decline",
            "maxLength": 2000,
            "minLength": 1
          }
        },
        "required": [
          "decision"
        ],
        "allOf": [
          {
            "if": {
              "properties": {
                "decision": {
                  "const": "declined"
                }
              },
              "required": [
                "decision"
              ]
            },
            "then": {
              "required": [
                "note"
              ]
            }
          }
        ]
      },
      "connections": {
        "success": "act-on-approval",
        "declined": "end"
      },
      "cases": [
        {
          "when": {
            "operator": "eq",
            "left": {
              "contextPath": "ask-approval.decision"
            },
            "right": "declined"
          },
          "output": "declined"
        }
      ]
    },
    {
      "id": "act-on-approval",
      "type": "agent-directive",
      "directive": "Replace with what happens after approval.",
      "completionCondition": "Replace with the observable result of acting on the approval.",
      "inputSchema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "result": {
            "type": "string",
            "description": "What was done, in one or two sentences",
            "minLength": 1,
            "maxLength": 2000
          }
        },
        "required": [
          "result"
        ]
      },
      "connections": {
        "success": "end"
      }
    },
    {
      "id": "end",
      "type": "end"
    }
  ]
}
